package com.richfield.smartpantry;
import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.recyclerview.widget.*;import java.util.*;
public class SuggestedRecipesActivity extends BaseActivity {DatabaseHelper db;@Override public void onCreate(Bundle b){super.onCreate(b);db=new DatabaseHelper(this);draw();}@Override protected void onResume(){super.onResume();if(db!=null)draw();}void draw(){LinearLayout r=page("Suggested Recipes");TextView expl=new TextView(this);expl.setText("Only recipes for which every ingredient and required quantity is already in your pantry.");expl.setTextSize(16);r.addView(expl);ArrayList<Recipe> matches=db.suggestions();if(matches.isEmpty()){TextView empty=new TextView(this);empty.setText("No recipes match your pantry yet — add more ingredients.");empty.setTextSize(18);empty.setPadding(16,48,16,16);r.addView(empty,new LinearLayout.LayoutParams(-1,0,1));}else{TextView count=new TextView(this);count.setText(matches.size()+" recipe(s) ready to make");count.setPadding(8,20,8,8);r.addView(count);RecyclerView list=new RecyclerView(this);list.setLayoutManager(new LinearLayoutManager(this));list.setAdapter(new RecipeAdapter(matches,x->{Intent i=new Intent(this,RecipeDetailActivity.class);i.putExtra("id",x.id);startActivity(i);}));r.addView(list,new LinearLayout.LayoutParams(-1,0,1));}nav(r);setContentView(r);}}
